stairs.cc.static string _annotation_exclusion_warn:
static string _annotation_exclusion_warning(level_id next_level_id)
{
    if (level_annotation_has("!", next_level_id)
        && next_level_id != level_id::current()
        && is_connected_branch(next_level_id))
    {
        crawl_state.level_annotation_shown = true;
        return make_stringf("Warning, next level annotated: <yellow>%s</yellow>",
                            get_level_annotation(next_level_id).c_str());
    }

    if (is_exclude_root(you.pos())
             && feat_is_travelable_stair(env.grid(you.pos()))
             && !strstr(get_exclusion_desc(you.pos()).c_str(), "cloud"))
    {
        return "This staircase is marked as excluded!";
    }

    return "";
}

stairs.cc.static string _target_exclusion_warning(:
static string _target_exclusion_warning()
{
    if (!feat_is_travelable_stair(env.grid(you.pos())))
        return "";

    LevelInfo *li = travel_cache.find_level_info(level_id::current());
    if (!li)
        return "";

    const stair_info *si = li->get_stair(you.pos());
    if (!si)
        return "";

    if (stairs_destination_is_excluded(*si))
        return "This staircase leads to a travel-excluded area!";

    return "";
}

stairs.cc.static string _bezotting_warning(:
static string _bezotting_warning(branch_type branch)
{
    if (branch == you.where_are_you || !bezotted_in(branch))
        return "";

    const int turns = turns_until_zot_in(branch);
    return make_stringf("You have just %d turns in %s to find a new floor before Zot consumes you.",
                        turns, branches[branch].longname);
}

stairs.cc.bool check_next_floor_warning(:
bool check_next_floor_warning()
{
    level_id  next_level_id = level_id::get_next_level_id(you.pos());

    crawl_state.level_annotation_shown = false;
    const string annotation_warning = _annotation_exclusion_warning(next_level_id);

    const string target_warning = _target_exclusion_warning();
    const string bezotting_warning = _bezotting_warning(next_level_id.branch);

    if (annotation_warning != "")
        mprf(MSGCH_PROMPT, "%s", annotation_warning.c_str());
    if (target_warning != "")
        mprf(MSGCH_PROMPT, "%s", target_warning.c_str());
    if (bezotting_warning != "")
        mprf(MSGCH_PROMPT, "%s", bezotting_warning.c_str());

    const bool might_be_dangerous = annotation_warning != ""
                                 || target_warning != ""
                                 || bezotting_warning != "";

    if (might_be_dangerous
        && !yesno("Enter next level anyway?", true, 'n', true, false))
    {
        canned_msg(MSG_OK);
        interrupt_activity(activity_interrupt::force);
        crawl_state.level_annotation_shown = false;
        return false;
    }
    return true;
}

stairs.cc.static void _climb_message(:
static void _climb_message(dungeon_feature_type stair, bool going_up,
                           branch_type old_branch)
{
    if (!is_connected_branch(old_branch))
        return;

    if (feat_is_portal(stair))
    {
        if (stair != DNGN_ENTER_CRUCIBLE)
            mpr("The world spins around you as you enter the gateway.");
    }
    else if (feat_is_escape_hatch(stair))
    {
        if (going_up)
            mpr("A mysterious force pulls you upwards.");
        else
        {
            mprf("You %s downwards.",
                 you.airborne() ? "fly" : "slide");
        }
        mpr("The hatch slams shut behind you.");
    }
    else if (feat_is_gate(stair))
    {
        mprf("You %s %s through the gate.",
             you.airborne() ? "fly" : "go",
             going_up ? "up" : "down");
    }
    else if (old_branch == BRANCH_SLIME && !you.royal_jelly_dead)
    {
        if (going_up)
            mpr("You ooze up the stairs.");   // Jiyva-worshippers only
        else
            mpr("You slide down the stairs, becoming coated in regenerative ooze.");
    }
    else if (stair != DNGN_ALTAR_IGNIS)
    {
        mprf("You %s %swards.",
             you.airborne() ? "fly" : "climb",
             going_up ? "up" : "down");
    }
}

stairs.cc.static bool _check_stairs(:
static bool _check_stairs(const dungeon_feature_type ftype, bool going_up)
{
    // If it's not bidirectional, check that the player is headed
    // in the right direction.
    if (!feat_is_bidirectional_portal(ftype))
    {
        if (feat_stair_direction(ftype) != (going_up ? CMD_GO_UPSTAIRS
                                                     : CMD_GO_DOWNSTAIRS))
        {
            if (ftype == DNGN_STONE_ARCH)
                mpr("There is nothing on the other side of the stone arch.");
            else if (ftype == DNGN_ABANDONED_SHOP)
                mpr("This shop has been abandoned, nothing of value remains.");
            else if (going_up)
                mpr("You can't go up here!");
            else
                mpr("You can't go down here!");
            return false;
        }
    }

    return true;
}

stairs.cc.static bool _check_fall_down_stairs(:
static bool _check_fall_down_stairs(const dungeon_feature_type ftype, bool going_up)
{
    if (!you.airborne()
        && you.confused()
        && !feat_is_escape_hatch(ftype)
        && !crawl_state.game_is_descent()
        && coinflip())
    {
        const char* fall_where = "down the stairs";
        if (!feat_is_staircase(ftype))
            fall_where = "through the gate";

        mprf("In your confused state, you trip and fall %s%s.",
             going_up ? "back " : "", fall_where);
        if (!feat_is_staircase(ftype))
            ouch(1, KILLED_BY_FALLING_THROUGH_GATE);
        else
            ouch(1, KILLED_BY_FALLING_DOWN_STAIRS);

        // Note that if going downstairs, this only does damage.
        // It doesn't cancel the level transition.
        if (going_up)
        {
            you.turn_is_over = true;
            return true;
        }
    }

    return false;
}

travel.cc.void deviant_route_warning::new_dest(:
void deviant_route_warning::new_dest(const level_pos &dest)
{
    if (target != dest)
    {
        warned = false;
        target = dest;
    }
}

travel.cc.bool deviant_route_warning::warn_continu:
bool deviant_route_warning::warn_continue_travel(
    const level_pos &dest, const level_id &deviant)
{
    // We've already prompted, don't ask again, on the player's head be it.
    if (target == dest && warned)
        return true;

    target = dest;
    const string prompt = make_stringf("Have to go through %s. Continue?",
                                       deviant.describe().c_str());
    // If the user says "Yes, shut up and take me there", we won't ask
    // again for that destination. If the user says "No", we will
    // prompt again.
    return warned = yesno(prompt.c_str(), true, 'n', true, false);
}

travel.cc.void start_explore(:
void start_explore(bool grab_items, bool skip_autorest)
{
    if (Hints.hints_explored)
        Hints.hints_explored = false;

    if (!i_feel_safe(true, true))
        return;

    if (should_fear_zot() && !yesno("Really explore while Zot is near?", false, 'n'))
    {
        canned_msg(MSG_OK);
        return;
    }

    you.running = (grab_items ? RMODE_EXPLORE_GREEDY : RMODE_EXPLORE);

    for (rectangle_iterator ri(0); ri; ++ri)
        if (env.map_knowledge(*ri).seen())
            env.map_seen.set(*ri);

    you.running.pos.reset();
    you.running.skip_autorest = skip_autorest;
    _start_running();
}

travel.cc.void do_explore_cmd(:
void do_explore_cmd(bool skip_autorest)
{
    if (you.berserk())
        mpr("Calm down first, please.");
    else                        // Start exploring
        start_explore(Options.explore_greedy, skip_autorest);
}

traps.cc.static string _net_immune_reason(:
static string _net_immune_reason()
{
    if (you.unrand_equipped(UNRAND_SLICK_SLIPPERS))
        return "You slip through the net.";
    else if (you.is_insubstantial() || you.is_amorphous())
        return "The net passes straight through you.";
    return "";
}

traps.cc.bool player::trap_in_web(:
bool player::trap_in_web()
{
   if (is_web_immune() || caught())
        return false;

    you.attribute[ATTR_HELD] = 1;
    you.redraw_armour_class = true;
    you.redraw_evasion      = true;
    quiver::set_needs_redraw();

    mpr("You are caught in a web!");

    return true;
}

traps.cc.bool player::trap_in_net(:
bool player::trap_in_net(bool real, bool quiet)
{
    if (!_net_immune_reason().empty() || caught())
        return false;

    you.attribute[ATTR_HELD] = NET_STARTING_DURABILITY;
    you.props[NET_IS_REAL_KEY].get_bool() = real;
    you.redraw_armour_class = true;
    you.redraw_evasion = true;
    quiver::set_needs_redraw();

    if (!quiet)
        mpr("You become entangled in the net!");

    stop_running();
    stop_delay(true); // even stair delays
    return true;
}

traps.cc.void player::struggle_against_net(:
void player::struggle_against_net()
{
    if (caught_by() == CAUGHT_WEB)
    {
        // Roll a chance to escape the web.
        if (x_chance_in_y(3, 10))
        {
            mpr("You struggle to detach yourself from the web.");
            return;
        }
        else
        {
            mpr("You disentangle yourself.");
            stop_being_caught();
            return;
        }
    }

    // Handle nets now.
    const int damage = random_range(1, 4);
    if (damage >= you.attribute[ATTR_HELD])
    {
        mprf("You %s the net and break free!", damage > 3 ? "shred" : "rip");
        stop_being_caught();
        return;
    }

    if (damage > 3)
        mpr("You tear a large gash into the net.");
    else
        mpr("You struggle against the net.");

    you.attribute[ATTR_HELD] -= damage;
}

main.cc.static bool _can_take_stairs(:
static bool _can_take_stairs(dungeon_feature_type ftype, bool down,
                             bool known_shaft)
{
    // Up and down both work for shops, portals, and altars.
    if (ftype == DNGN_ENTER_SHOP || feat_is_altar(ftype))
    {
        if (crawl_state.doing_prev_cmd_again)
        {
            mprf("You can't repeat %s actions.",
                ftype == DNGN_ENTER_SHOP ? "shop" : "altar");
            crawl_state.cancel_cmd_all();
        }
        else if (you.berserk())
            canned_msg(MSG_TOO_BERSERK);
        else if (ftype == DNGN_ENTER_SHOP) // don't convert to capitalism
            shop();
        else
            try_god_conversion(feat_altar_god(ftype));
        // Even though we may have "succeeded", return false so we don't keep
        // trying to go downstairs.
        return false;
    }

    // Immobile
    if (you.cannot_move())
    {
        canned_msg(MSG_CANNOT_MOVE);
        return false;
    }

    // ATTR_HELD is intentionally not tested here, it's handled in _take_stairs()

    // Bidirectional, but not actually a portal - allowed while mesmerised, but
    // not when otherwise unable to move.
    if (ftype == DNGN_PASSAGE_OF_GOLUBRIA || ftype == DNGN_TRANSPORTER)
        return true;
    else if (you.duration[DUR_VAINGLORY])
    {
        mpr("It simply wouldn't do to leave so soon after announcing yourself.");
        return false;
    }

    // Mesmerised
    if (you.beheld() && !you.confused())
    {
        const monster* beholder = you.get_any_beholder();
        mprf("You cannot move away from %s!",
             beholder->name(DESC_THE, true).c_str());
        return false;
    }

    // If it's not bidirectional, check that the player is headed
    // in the right direction.
    if (!feat_is_bidirectional_portal(ftype))
    {
        if (feat_stair_direction(ftype) != (down ? CMD_GO_DOWNSTAIRS
                                                 : CMD_GO_UPSTAIRS)
            // probably shouldn't be passed known_shaft=true
            // if going up, but just in case...
            && (!down || !known_shaft))
        {
            if (ftype == DNGN_STONE_ARCH)
                mpr("There is nothing on the other side of the stone arch.");
            else if (ftype == DNGN_ABANDONED_SHOP)
                mpr("This shop appears to be closed.");
            else if (ftype == DNGN_SEALED_STAIRS_UP
                     || ftype == DNGN_SEALED_STAIRS_DOWN )
            {
                mpr("A magical barricade bars your way!");
            }
            else if (down)
                mpr("You can't go down here!");
            else
                mpr("You can't go up here!");
            return false;
        }
    }

    // Rune locks
    switch (ftype)
    {
    case DNGN_EXIT_VAULTS:
        if (runes_in_pack() < 1)
        {
            mpr("You need a rune to leave the Vaults.");
            return false;
        }
        break;
    case DNGN_ENTER_ZOT:
        if (runes_in_pack() < ZOT_ENTRY_RUNES && !crawl_state.game_is_descent())
        {
            mprf("You need at least %d runes to enter the Realm of Zot.",
                 ZOT_ENTRY_RUNES);
            return false;
        }
        break;
    default:
        break;
    }

    if (player_in_branch(BRANCH_SLIME) && !down && you.depth > 1
            && !you_worship(GOD_JIYVA) && !you.royal_jelly_dead)
    {
        mpr("The stairs are too slimy for you to climb back up!");
        return false;
    }

    return true;
}
